 auto safe=[=](std::function<void()> work){try{work();}catch(const std::exception& e){if(statusGuard)statusGuard->setText(QString::fromUtf8(e.what()));}};auto run=[=](std::function<QJsonObject()> work,std::function<void(QJsonObject)> done){business::require(!state->busy,"上一项只读核验尚未结束");state->busy=true;main->setEnabled(false);status->setText("正在只读核验/隔离演练；生产业务库不写入");struct Result{QJsonObject value;QString error;};auto result=std::make_shared<Result>();auto thread=QThread::create([=]{try{result->value=work();}catch(const std::exception& e){result->error=QString::fromUtf8(e.what());}});QObject::connect(thread,&QThread::finished,thread,&QObject::deleteLater);QObject::connect(thread,&QThread::finished,page,[=]{state->busy=false;main->setEnabled(true);if(!result->error.isEmpty())status->setText(result->error);else safe([=]{done(result->value);});});thread->start();};auto render=[=]{summary->setPlainText(state->plan.isEmpty()?"暂无恢复计划":dataSafety::readPlan(state->plan));};auto persist=[=]{dataSafety::safeDraft(input->toPlainText());auto row=store->put("drafts",QJsonObject{{"input",input->toPlainText()},{"checksum",checksum->text()}},state->draftRevision);state->draftRevision=row["recordRevision"].toString();};auto restore=[=]{auto p=store->get("policy"),d=store->get("drafts"),s=store->get("stages");auto values=store->settings();state->policyRevision=p["recordRevision"].toString();state->draftRevision=d["recordRevision"].toString();state->stageRevision=s["recordRevision"].toString();state->plan=s["data"].toObject()["plan"].toObject();QSignalBlocker a(input),b(checksum);input->setPlainText(d["data"].toObject()["input"].toString());checksum->setText(d["data"].toObject()["checksum"].toString());limit->setValue(values["maxPreviewMiB"].toInt());requireSha->setChecked(values["requireExternalChecksum"].toBool());partial->setChecked(values["allowPartialBusinessBackup"].toBool());render();};
 auto prepare=[=](const QByteArray& bytes,const QString& name){const auto expected=checksum->text();const auto revision=state->stageRevision;run([=]{auto before=business->backup();auto plan=dataSafety::inspect(bytes,store->settings(),before,expected,name);plan=dataSafety::validateIsolated(plan,before);return store->stage(plan,bytes,revision);},[=](QJsonObject row){state->stageRevision=row["recordRevision"].toString();state->plan=row["data"].toObject()["plan"].toObject();render();status->setText(state->plan["eligible"].toBool()?"隔离兼容性核验通过；仅生成计划，尚未恢复":"计划只供审阅；格式/摘要/部分包限制尚不允许交接");});};QObject::connect(input,&QPlainTextEdit::textChanged,page,[=]{safe(persist);});QObject::connect(checksum,&QLineEdit::textChanged,page,[=]{safe(persist);});QObject::connect(reload,&QPushButton::clicked,page,[=]{safe(restore);});QObject::connect(savePolicy,&QPushButton::clicked,page,[=]{safe([=]{auto settings=dataSafety::policy(QJsonObject{{"maxPreviewMiB",limit->value()},{"requireExternalChecksum",requireSha->isChecked()},{"allowPartialBusinessBackup",partial->isChecked()}});auto row=store->put("policy",settings,state->policyRevision);state->policyRevision=row["recordRevision"].toString();status->setText("已保存且用于实际读取/解析/交接；旧计划须重新核验");});});QObject::connect(preview,&QPushButton::clicked,page,[=]{safe([=]{prepare(input->toPlainText().toUtf8(),"粘贴UTF8文本");});});QObject::connect(choose,&QPushButton::clicked,page,[=]{safe([=]{auto path=QFileDialog::getOpenFileName(page,"选择已有备份",{},"JSON (*.json)");if(path.isEmpty())return;QFile file(path);auto maximum=store->settings()["maxPreviewMiB"].toInt()*1024*1024;business::require(file.open(QIODevice::ReadOnly)&&file.size()<=maximum,"文件不可读或超过已保存上限");prepare(file.readAll(),QFileInfo(path).fileName());});});QObject::connect(recheck,&QPushButton::clicked,page,[=]{safe([=]{prepare(store->source(state->stageRevision),state->plan["sourceName"].toString());});});QObject::connect(original,&QPushButton::clicked,page,[=]{safe([=]{auto bytes=store->source(state->stageRevision);dataSafety::inspect(bytes,store->settings(),business->backup(),state->plan["expectedSourceSha256"].toString());read(QString::fromUtf8(bytes));});});QObject::connect(cancel,&QPushButton::clicked,page,[=]{safe([=]{auto row=store->put("stages",QJsonObject{},state->stageRevision);state->stageRevision=row["recordRevision"].toString();state->plan={};render();});});QObject::connect(route,&QPushButton::clicked,page,[=]{safe([=]{auto bytes=store->source(state->stageRevision);const auto plan=state->plan;business::require(checksum->text().trimmed().toLower()==plan["expectedSourceSha256"],"外部摘要输入已变，请重新核验");run([=]{auto before=business->backup();business::require(dataSafety::baselineHash(before)==plan["baselineHash"]&&dataSafety::fingerprint(store->settings())==plan["policyHash"],"当前数据或安全设置已变化，请重新核验；未交接");auto fresh=dataSafety::validateIsolated(dataSafety::inspect(bytes,store->settings(),before,plan["expectedSourceSha256"].toString(),plan["sourceName"].toString()),before);business::require(fresh["eligible"].toBool()&&fresh["id"]==plan["id"],"计划未达到可交接条件");return fresh;},[=](QJsonObject fresh){business::require(bool(opener),"宿主未接既有恢复入口");opener(fresh);if(statusGuard)statusGuard->setText("已交给既有备份恢复入口；未自动应用，仍需先备份和确认");});});});
 QObject::connect(refresh,&QPushButton::clicked,page,[=]{safe([=]{business::require(bool(inventory),"宿主尚未提供批准的数据位置清单");auto entries=inventory();run([=]{QJsonArray rows;for(auto v:entries)rows.append(dataSafety::diagnose(v.toObject()));return QJsonObject{{"entries",rows}};},[=](QJsonObject out){state->inventory=entries;paths->clear();int index=0;for(auto v:out["entries"].toArray()){auto r=v.toObject();auto item=new QListWidgetItem(r["label"].toString(r["id"].toString())+" · "+(r["present"].toBool()?"已存在":"缺失"),paths);item->setData(Qt::UserRole,r);item->setData(Qt::UserRole+1,index++);}store->put("diagnostics",out,store->get("diagnostics")["recordRevision"].toString());status->setText("已读取实际位置；文件时间不是行情/来源内容时间。点击库检查才执行只读完整性核验");});});});QObject::connect(details,&QPushButton::clicked,page,[=]{safe([=]{business::require(paths->currentItem(),"请选择实际数据位置");read("来源/asOf为宿主提供；checkedAt为本次检查。未列入业务备份的独立库/缓存仍需各模块自己的备份。\n"+QString::fromUtf8(QJsonDocument(paths->currentItem()->data(Qt::UserRole).toJsonObject()).toJson()));});});QObject::connect(check,&QPushButton::clicked,page,[=]{safe([=]{business::require(paths->currentItem(),"请选择实际数据位置");int index=paths->currentItem()->data(Qt::UserRole+1).toInt();const auto entry=state->inventory[index].toObject();run([=]{return dataSafety::diagnose(entry,true);},[=](QJsonObject out){read("只读完整性检查；未读取记录正文或凭据\n"+QString::fromUtf8(QJsonDocument(out).toJson()));status->setText("库诊断完成；未重建、清理、迁移或写入数据");});});});QObject::connect(exportButton,&QPushButton::clicked,page,[=]{safe([=]{auto diagnostics=store->get("diagnostics")["data"].toObject();auto receipt=dataSafety::receipt(state->plan,diagnostics);auto bytes=QJsonDocument(receipt).toJson();auto path=QFileDialog::getSaveFileName(page,"保存核验摘要","data-safety-check.json","JSON (*.json)");if(path.isEmpty())return;QSaveFile file(path);business::require(file.open(QIODevice::WriteOnly)&&file.write(bytes)==bytes.size()&&file.commit(),"核验摘要保存失败");});});safe(restore);return page;
